/** Msg defines the Msg service. */
export interface Msg {
  /**
   * UpdateParams defines a (governance) operation for updating the module
   * parameters. The authority defaults to the x/gov module account.
   */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
  /** ApplyParticipant defines the ApplyParticipant RPC. */
  ApplyParticipant(request: MsgApplyParticipant): Promise<MsgApplyParticipantResponse>;
  /** SendPayment defines the SendPayment RPC. */
  SendPayment(request: MsgSendPayment): Promise<MsgSendPaymentResponse>;
  /**
   * ApproveParticipant defines the ApproveParticipant RPC. It is
   * authority-gated (the x/gov module account) and approves or rejects a
   * pending participant application submitted via MsgApplyParticipant.
   */
  ApproveParticipant(request: MsgApproveParticipant): Promise<MsgApproveParticipantResponse>;
  /**
   * RegisterCustomer records that an account banks with the signing
   * participant, which is what entitles a payment from that account to name
   * the participant as its instructing agent.
   */
  RegisterCustomer(request: MsgRegisterCustomer): Promise<MsgRegisterCustomerResponse>;
  /**
   * SetPayloadStore records where an approved participant serves the encrypted
   * payloads of the payments it instructed.
   */
  SetPayloadStore(request: MsgSetPayloadStore): Promise<MsgSetPayloadStoreResponse>;
}

